"class Conversation {
  final String id;
  final String colleagueName;
  final String colleagueRole;
  final String colleagueAvatarUrl;
  final bool isOnline;
  final int unreadCount;
  final String lastMessagePreview;
  final DateTime lastMessageTime;

  Conversation({
    required this.id,
    required this.colleagueName,
    required this.colleagueRole,
    required this.colleagueAvatarUrl,
    required this.isOnline,
    required this.unreadCount,
    required this.lastMessagePreview,
    required this.lastMessageTime,
  });

  factory Conversation.fromJson(Map<String, dynamic> json) {
    // TODO: Update field names based on the final backend contract
    return Conversation(
      id: json['id'] as String,
      colleagueName: json['colleagueName'] as String,
      colleagueRole: json['colleagueRole'] as String,
      colleagueAvatarUrl: json['colleagueAvatarUrl'] as String,
      isOnline: json['isOnline'] as bool? ?? false,
      unreadCount: json['unreadCount'] as int? ?? 0,
      lastMessagePreview: json['lastMessagePreview'] as String? ?? '',
      lastMessageTime: json['lastMessageTime'] != null
          ? DateTime.parse(json['lastMessageTime'] as String)
          : DateTime.now(),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'colleagueName': colleagueName,
      'colleagueRole': colleagueRole,
      'colleagueAvatarUrl': colleagueAvatarUrl,
      'isOnline': isOnline,
      'unreadCount': unreadCount,
      'lastMessagePreview': lastMessagePreview,
      'lastMessageTime': lastMessageTime.toIso8601String(),
    };
  }
}

