    super.initState();
    _filteredConversations = MockChatData.conversations;
    _searchController.addListener(_onSearchChanged);
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  void _onSearchChanged() {
    final query = _searchController.text.toLowerCase();
    setState(() {
      if (query.isEmpty) {
        _filteredConversations = MockChatData.conversations;
      } else {
        _filteredConversations = MockChatData.conversations.where((conv) {
          return conv.colleagueName.toLowerCase().contains(query) ||
